    n, m, k = map(int, sys.stdin.readline().split())
    c = list(map(int, sys.stdin.readline().split()))
    acquaintances = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]

    group_students = defaultdict(set)
    for i in range(n):
        group_students[c[i]].add(i)

    graph = defaultdict(set)
    for a, b in acquaintances:
        graph[a - 1].add(b - 1)
        graph[b - 1].add(a - 1)

    def is_bipartite(group1, group2):
        students = list(group_students[group1] | group_students[group2])
        color = {student: -1 for student in students}
        for start in students:
            if color[start] == -1:
                queue = [start]
                color[start] = 0
                while queue:
                    u = queue.pop()
                    for v in graph[u]:
                        if v in color:
                            if color[v] == color[u]:
                                return False
                        else:
                            color[v] = 1 - color[u]
                            queue.append(v)
        return True

    count = 0
    for i in range(1, k + 1):
        for j in range(i + 1, k + 1):
            if is_bipartite(i, j):
                count += 1

    print(count)

